83	  async init(canvas: HTMLCanvasElement): Promise<void> {
84	    this._canvas = canvas;
85	
86	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
87	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
88	    renderer.setClearAlpha(0);
89	    this._renderer = renderer;
90	
91	    const scene = new THREE.Scene();
92	    this._scene = scene;
93	
94	    const w = Math.max(canvas.clientWidth, 1);
95	    const h = Math.max(canvas.clientHeight, 1);
96	    // Frontal elevated view: ring curves left/right into depth
97	    const camera = new THREE.PerspectiveCamera(65, w / h, 0.1, 1000);
98	    camera.position.set(0, 3, 22);
99	    camera.lookAt(0, 0, 0);
100	    this._camera = camera;
101	
102	    scene.add(new THREE.AmbientLight(0xffffff, 1.0));
103	
104	    const group = new THREE.Group();
105	    this._group = group;
106	    scene.add(group);
107	
108	    let imageUrls: string[] = [];
109	    try {
110	      const response = await fetchWorksList(0, MAX_IMAGES, null);
111	      imageUrls = response.items
112	        .filter((item: WorkApiItem) => item.thumbnailImage.length > 0)
113	        .map((item: WorkApiItem) => item.thumbnailImage)
114	        .slice(0, MAX_IMAGES);
115	    } catch {
116	      // fallback to colored cards
117	    }
118	
119	    if (this._disposed) return;
120	
121	    if (imageUrls.length > 0) {
122	      const loader = new THREE.TextureLoader();
123	      const textures = await Promise.all(
124	        imageUrls.map((url) => loadTexture(loader, url)),
125	      );
126	      if (this._disposed) return;
127	      const radius = computeRadius(textures.length);
128	      textures.forEach((texture, i) => {
129	        if (texture) this._textures.push(texture);
130	        this._addCard(group, i, textures.length, texture, radius);
131	      });
132	    } else {
133	      const radius = computeRadius(FALLBACK_COUNT);
134	      for (let i = 0; i < FALLBACK_COUNT; i++) {
135	        this._addCard(group, i, FALLBACK_COUNT, null, radius);
136	      }
137	    }
138	
139	    this._syncSize();
140	    this._observeResize();
141	    this._observeVisibility();
142	  }
143	
144	  dispose(): void {
145	    this._disposed = true;
146	    this._stopRaf();
147	
148	    this._resizeObserver?.disconnect();
149	    this._resizeObserver = null;
150	
151	    this._intersectionObserver?.disconnect();
152	    this._intersectionObserver = null;
153	
154	    this._geometries.forEach((g) => g.dispose());
155	    this._geometries = [];
156	
157	    this._materials.forEach((m) => m.dispose());
158	    this._materials = [];
159	
160	    this._textures.forEach((t) => t.dispose());
161	    this._textures = [];
162	
163	    this._renderer?.dispose();
164	    this._renderer?.forceContextLoss();
165	    this._renderer = null;
166	    this._scene = null;
167	    this._camera = null;
168	    this._group = null;
169	    this._canvas = null;
170	  }
171	
172	  private _addCard(
173	    group: THREE.Group,
174	    index: number,
175	    total: number,
176	    texture: THREE.Texture | null,
177	    radius: number,
178	  ): void {
179	    const angle = (index / total) * Math.PI * 2;
180	    const x = radius * Math.cos(angle);
181	    const z = radius * Math.sin(angle);
182	
183	    const geo = new THREE.PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
184	    this._geometries.push(geo);
185	
186	    const mat = createCardMaterial(
187	      texture,
188	      FALLBACK_COLORS[index % FALLBACK_COLORS.length],
189	    );
190	    this._materials.push(mat);
191	
192	    const mesh = new THREE.Mesh(geo, mat);
193	    mesh.position.set(x, 0, z);
194	    // rotation.y so the front face (+Z normal) points radially outward from center
195	    mesh.rotation.y = Math.PI / 2 - angle;
196	    group.add(mesh);
197	  }
198	
199	  private readonly _tick = (): void => {
200	    if (this._disposed || !this._rendering) return;
201	    const p = this._scrollProgress;
202	    const speed = ROTATION_SPEED_Y * (1 + p * 1.8);
203	    if (this._group) this._group.rotation.y += speed;
204	    if (this._camera) {
205	      this._camera.position.y = 3 - p * 3;
206	      this._camera.position.z = 22 - p * 6;
207	      this._camera.lookAt(0, 0, 0);
208	    }
209	    if (this._renderer && this._scene && this._camera) {
210	      this._renderer.render(this._scene, this._camera);
211	    }
212	    this._rafId = requestAnimationFrame(this._tick);
213	  };
214	
215	  private _startRaf(): void {
216	    if (this._rafId !== null || this._disposed) return;
217	    this._rendering = true;
218	    this._rafId = requestAnimationFrame(this._tick);
219	  }
220	
221	  private _stopRaf(): void {
222	    this._rendering = false;
223	    if (this._rafId !== null) {
224	      cancelAnimationFrame(this._rafId);
225	      this._rafId = null;
226	    }
227	  }
228	
229	  private _syncSize(): void {
230	    const canvas = this._canvas;
231	    const renderer = this._renderer;
232	    const camera = this._camera;
233	    if (!canvas || !renderer || !camera) return;
234	    const w = canvas.clientWidth;
235	    const h = canvas.clientHeight;
236	    if (w <= 0 || h <= 0) return;
237	    renderer.setSize(w, h, false);
238	    camera.aspect = w / h;
239	    camera.updateProjectionMatrix();
240	  }
241	
242	  private _observeResize(): void {
243	    if (!this._canvas) return;
244	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
245	    this._resizeObserver.observe(this._canvas);
246	  }
247	
248	  private _observeVisibility(): void {
249	    if (!this._canvas) return;
250	    this._intersectionObserver = new IntersectionObserver(
251	      (entries) => {
252	        if (entries[0]?.isIntersecting) {
253	          this._startRaf();
254	        } else {
255	          this._stopRaf();
256	        }
257	      },
258	      { threshold: 0 },
259	    );
260	    this._intersectionObserver.observe(this._canvas);
261	  }
262	}
